preciser("templates/index.html", "Accueil", [["#salut","Phrase Bonjour, remplie par remplirNavigation si un compte est connecté."],["#selecteur","Trois listes matière, classe, spécialité, construites par monterSelecteur."],["#statut","Message de succès ou d'erreur de l'envoi et de la recherche."],["#form-recherche","Champs q, auteur, etoiles_min. Matière, classe et spécialité n'y sont pas : elles sont dans le menu."],["#resultats","Cartes renvoyées par la recherche."],["#fichiers","Cartes du cours choisi dans le menu."],["#invite-connexion","Lien vers la connexion, caché tant qu'un cours est choisi sans compte."],["#form-envoi","Fichier, titre, description. Caché sans cours ou sans compte. Pas de champ auteur."],["name=file","Fichier à publier. accept liste les suffixes autorisés, le serveur revérifie."],["name=title","Titre, maxlength 120, required."],["name=desc","Description, maxlength 2000, required."]], ["Le cours choisi charge les fiches sans bouton supplémentaire.","La recherche envoie seulement les champs remplis vers /info/recherche.","Publier poste le formulaire vers /upload/matière/classe/spécialité."]);
preciser("templates/user_dashboard.html", "Espace élève", [["#envoyes","Liste des fiches publiées par le compte. espace.js y met Modifier et Supprimer."],["#telecharges","Liste des fiches déjà téléchargées. Pas de bouton de suppression : ce ne sont pas ses fichiers."],["#fiches-data","JSON déjà rendu par le serveur : envoyes et telecharges, avec etoiles et etoile_moi."],["lien audit","href /users/audit. Mène au relevé de ses seules fiches."]], ["La page ne rappelle pas les fiches au serveur : elles sont dans fiches-data.","Supprimer une fiche recharge toute la page pour faire disparaître aussi le lien de téléchargement."]);
preciser("templates/audit_perso.html", "Audit de mes fiches", [["#zone-resume","Grille des chiffres : nombre, volume, étoiles, téléchargements, commentaires."],["#zone-plus","Phrase sur la fiche personnelle la plus étoilée, ou l'absence d'étoile."],["#zone-fiches","Tableau titre, cours, étoiles, commentaires, taille."],["#zone-commentaires","Commentaires que ce compte a le droit de lire. Ceux réservés à l'équipe n'y sont pas."],["#audit-data","JSON du premier relevé. Actualiser le remplace par /users/audit.json."],["#bouton-actualiser","Relance la lecture du relevé sans changer de compte."]], ["Aucun identifiant d'un autre compte n'est dans l'adresse.","Le script audit_perso.js peint les zones à partir du JSON."]);
preciser("templates/audit.html", "Audit du propriétaire", [["#bouton-site","Suspendre ou réactiver. Le texte change selon audit.site.suspendu."],["#bouton-actualiser","Redemande /owner/audit.json."],["#zone-sessions","Sessions ouvertes, badge en ligne si activité de moins de 15 minutes."],["#zone-stockage","Tailles de uploads/, matiere/, base, instance, orphelins, disque."],["#zone-comptes","Nombre de comptes par rôle, créations récentes, activité."],["#zone-etoiles","Total d'étoiles et nombre de matières qui en ont au moins une."],["#zone-etoile-globale","La seule fiche la plus étoilée du site."],["#zone-etoiles-matiere","Les fiches en tête de chaque matière, y compris les égalités."],["#audit-data","Premier relevé inclus dans la page pour l'affichage immédiat."]], ["Toutes les zones sont vides dans le HTML. audit.js les remplit.","La page se rafraîchit seule toutes les 20 secondes si l'onglet est visible."]);
preciser("templates/staff_dashboard.html", "Espace modération ou administration", [["#staff-config","Attribut data-prefix : /admin ou /moderator. Le script ne devine pas le rôle."],["#form-recherche","Recherche de fiches : texte, auteur, étoiles minimum."],["#resultats","Résultats de recherche, avec Modifier et Supprimer."],["#selecteur","Menu matière, classe, spécialité."],["#fichiers","Fiches du cours choisi."],["comptes_url","Lien vers la page des comptes du même préfixe."]], ["Modifier ouvre prefixe/dashboard/modify/identifiant.","Supprimer appelle prefixe/dashboard/delete/identifiant puis recharge la page."]);
preciser("templates/comptes.html", "Gestion des comptes", [["#form-recherche","Champs q, role, etat. Le mot de passe n'existe pas dans ce formulaire."],["#bouton-tous","Réaffiche la liste complète déjà présente dans comptes-data."],["#corps-comptes","Lignes construites par comptes.js."],["#comptes-config","data-prefix, data-roles (1 si le rôle peut être changé), data-moi (id du compte connecté)."],["#comptes-data","JSON de tous les profils publics au chargement."]], ["La recherche interroge prefixe/comptes/recherche.","Changer un rôle ou suspendre recharge la page après la réponse du serveur.","Le propriétaire n'a pas de bouton : la ligne dit seulement Propriétaire."]);
preciser("templates/modifier.html", "Modifier une fiche", [["#form-modifier","data-save-url est l'adresse d'enregistrement, data-retour-url le lien de retour."],["#selecteur","Cours actuel, prérempli depuis fiche-data."],["name=title","Titre actuel, maxlength 120."],["name=desc","Description actuelle, maxlength 2000."],["name=file","Nouveau fichier facultatif. Vide : l'ancien document est conservé."],["#fiche-data","JSON public de la fiche à modifier."]], ["Le script poste le formulaire vers data-save-url.","L'auteur affiché n'est pas un champ : le serveur le conserve."]);
preciser("templates/erreur.html", "Page d'erreur", [["message","Texte fourni par le serveur, échappé par le modèle. Il n'est pas réinterprété comme du HTML."]], ["Affichée quand wants_html est vrai et qu'une erreur HTTP doit rester lisible."]);
preciser("templates/suspendu.html", "Site suspendu", [["depuis","Date lisible de la suspension, ou rien si la date est absente."]], ["Montrée avec le code 503 aux visiteurs qui ne sont pas le propriétaire.","La connexion reste possible pour que le propriétaire puisse revenir."]);
preciser("auth/login/login.html", "Connexion", [["name=username","Identifiant, maxlength 80, autocomplete username."],["name=password","Mot de passe, maxlength 200, autocomplete current-password. Il part en JSON, pas dans l'adresse."],["#login-config","JSON { next }. next a déjà été nettoyé par safe_next_url."],["site_suspendu","Si vrai, une phrase rouge prévient que seul le propriétaire peut entrer."]], ["login.js poste /auth/login.","Si must_change_password est vrai, le navigateur va vers /auth/mot-de-passe et ignore next."]);
preciser("auth/logout/logout.html", "Déconnexion", [["#form-sortie","Formulaire confirmé par un bouton. La sortie est un POST, pour envoyer le jeton CSRF."]], ["logout.js poste /auth/logout puis ramène à l'accueil."]);
preciser("auth/mot-de-passe/mot-de-passe.html", "Mot de passe", [["obligatoire","True à la première connexion. Change le titre et retire le lien vers l'espace."],["name=actuel","Mot de passe actuel, maxlength 200, autocomplete current-password."],["name=nouveau","Nouveau mot de passe, minlength 10, maxlength 200, autocomplete new-password."],["name=confirmation","Seconde saisie, mêmes limites. Le serveur exige l'égalité."],["#mot-de-passe-config","JSON obligatoire et retour, pour le script."],["retour","Adresse de l'espace du rôle, lien affiché seulement si le changement n'est pas obligatoire."]], ["Le script poste actuel, nouveau et confirmation vers /auth/mot-de-passe.","À la réussite, la page va vers home renvoyé par le serveur.","À la première connexion, le seul autre lien est la déconnexion."]);
preciser("static/style.css", ":root", [["--encre","Couleur du texte principal, #1c2430."],["--encre-douce","Notes et métadonnées, #4d5968."],["--papier","Fond de page, #f4efe4."],["--carte","Fond des panneaux, #fffdf8."],["--ligne","Bordures, #e4d9c6."],["--foret","Bouton principal et liens, #1d6b4f."],["--foret-fonce","Survol du bouton et texte du bouton secondaire, #14543d."],["--danger","Suppression et erreurs, #8d2f2f."],["--focus","Contour clavier, #b86b12, 3 pixels."],["--ombre","Ombre des panneaux, noire très transparente."]], ["La règle :root fixe chacune de ces propriétés dans static/style.css.","--encre : Couleur du texte principal, #1c2430.","--encre-douce : Notes et métadonnées, #4d5968.","--papier : Fond de page, #f4efe4.","--carte : Fond des panneaux, #fffdf8.","--ligne : Bordures, #e4d9c6.","--foret : Bouton principal et liens, #1d6b4f.","--foret-fonce : Survol du bouton et texte du bouton secondaire, #14543d.","--danger : Suppression et erreurs, #8d2f2f.","--focus : Contour clavier, #b86b12, 3 pixels.","--ombre : Ombre des panneaux, noire très transparente."]);
preciser("static/style.css", "body", [["margin","0, pour coller le bandeau au bord."],["background","Dégradé vert très léger en haut à gauche, puis --papier."],["font-family","Segoe UI, Helvetica Neue, sans-serif."],["line-height","1.5."]], ["La règle body fixe chacune de ces propriétés dans static/style.css.","margin : 0, pour coller le bandeau au bord.","background : Dégradé vert très léger en haut à gauche, puis --papier.","font-family : Segoe UI, Helvetica Neue, sans-serif.","line-height : 1.5."]);
preciser("static/style.css", ".bouton", [["background","--foret."],["color","blanc."],["border-radius","999px, forme de pilule."],["padding","0.6rem 1rem."]], ["La règle .bouton fixe chacune de ces propriétés dans static/style.css.","background : --foret.","color : blanc.","border-radius : 999px, forme de pilule.","padding : 0.6rem 1rem."]);
preciser("static/style.css", ".etoile", [["aria-pressed=true","Fond #f4e4b3, texte #6a4b00, bord #c4a15a. L'étoile est posée."]], ["La règle .etoile fixe chacune de ces propriétés dans static/style.css.","aria-pressed=true : Fond #f4e4b3, texte #6a4b00, bord #c4a15a. L'étoile est posée."]);
